Deployment Verification Tests validate deployment success beyond smoke tests. Run immediately post-deployment to verify: configuration correct, integrations working, data integrity maintained, performance acceptable. vs Smoke tests: more comprehensive, longer duration (5-15 min), tests edge cases. Example DVT suite:
@SpringBootTest
@ActiveProfiles("dvt")
public class DeploymentVerificationTests {

  @Test
  public void verifyAllActuatorEndpointsAccessible() {
    // /health, /metrics, /info all respond 200
    actuatorEndpoints.forEach(endpoint -> {
      ResponseEntity<String> response = restTemplate.getForEntity(baseUrl + endpoint, String.class);
      assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
    });
  }

  @Test
  public void verifyDatabaseMigrationsApplied() {
    // Check Flyway schema version
    int currentVersion = jdbcTemplate.queryForObject(
      "SELECT MAX(version) FROM flyway_schema_history", Integer.class);
    assertThat(currentVersion).isEqualTo(expectedVersion);
  }

  @Test
  public void verifyAllRequiredConfigurationPresent() {
    assertThat(env.getProperty("spring.datasource.url")).isNotNull();
    assertThat(env.getProperty("jwt.secret")).isNotNull();
    assertThat(env.getProperty("payment.gateway.url")).isNotNull();
  }

  @Test
  public void verifyExternalServiceConnectivity() {
    // Test auth service
    ResponseEntity<String> authResponse = restTemplate.getForEntity(
      authServiceUrl + "/health", String.class);
    assertThat(authResponse.getStatusCode()).isEqualTo(HttpStatus.OK);

    // Test payment gateway (test endpoint)
    PaymentGatewayResponse gatewayResponse = paymentGatewayClient.testConnection();
    assertThat(gatewayResponse.isHealthy()).isTrue();
  }

  @Test
  public void verifyEndToEndWorkflow() {
    // Create order, process payment, verify status
    Order order = orderClient.createOrder(testOrderRequest);
    Payment payment = paymentService.processPayment(order.getId(), testPaymentMethod);
    assertThat(payment.getStatus()).isEqualTo(PaymentStatus.COMPLETED);

    // Verify order status updated
    Order updatedOrder = orderClient.getOrder(order.getId());
    assertThat(updatedOrder.getStatus()).isEqualTo(OrderStatus.PAID);
  }

  @Test
  public void verifyPerformanceWithinThresholds() {
    long startTime = System.currentTimeMillis();
    PaymentResponse response = paymentService.processPayment(testPayment);
    long duration = System.currentTimeMillis() - startTime;

    assertThat(duration).isLessThan(1000); // <1 second
    assertThat(response).isNotNull();
  }

  @Test
  public void verifyFeatureFlagsConfiguration() {
    assertThat(featureFlags.isEnabled("new-payment-flow")).isEqualTo(expectedFlagState);
  }
}

