Artifacts (JAR, WAR, Docker images) must be versioned, stored, and traceable. Strategy: 1) Semantic versioning (MAJOR.MINOR.PATCH), 2) Build once, deploy many, 3) Artifact repository (Nexus, Artifactory, Docker registry), 4) Immutable artifacts (never overwrite), 5) Git commit SHA in version. Example Maven configuration:
<version>2.3.${revision}</version>
<properties>
  <revision>0-SNAPSHOT</revision>
</properties>

Jenkins sets version:
pipeline {
  environment {
    GIT_COMMIT_SHORT = sh(returnStdout: true, script: 'git rev-parse --short HEAD').trim()
    BUILD_VERSION = "2.3.${BUILD_NUMBER}-${GIT_COMMIT_SHORT}"
  }
  stages {
    stage('Build') {
      steps {
        sh "mvn versions:set -DnewVersion=${BUILD_VERSION}"
        sh 'mvn clean package'
      }
    }
    stage('Publish Artifact') {
      steps {
        // Maven artifact
        sh 'mvn deploy:deploy-file -DrepositoryId=nexus -Durl=http://nexus:8081/repository/maven-releases/'

        // Docker image
        sh "docker build -t company.registry.io/payment:${BUILD_VERSION} ."
        sh "docker tag company.registry.io/payment:${BUILD_VERSION} company.registry.io/payment:latest"
        sh "docker push company.registry.io/payment:${BUILD_VERSION}"
        sh "docker push company.registry.io/payment:latest"

        // Store metadata
        sh """
          cat > artifact-metadata.json <<EOF
          {
            "service": "payment",
            "version": "${BUILD_VERSION}",
            "gitCommit": "${GIT_COMMIT}",
            "gitBranch": "${GIT_BRANCH}",
            "buildNumber": "${BUILD_NUMBER}",
            "buildTimestamp": "${new Date()}",
            "builtBy": "${BUILD_USER}"
          }
        EOF
        """
        sh "curl -X POST nexus/metadata -F file=@artifact-metadata.json"
      }
    }
  }
}

